-- Visible rifle follows the authored wrist transform instead of GTA's weapon
-- task. Local sandbox only. The actual inventory weapon still owns ammo/damage.
CidadeCombatWeapon={}
local visual,owner,mount
local function wristFrame()
    local p=GetPedBoneCoords(owner,57005,0.0,0.0,0.0)
    local x=GetPedBoneCoords(owner,57005,1.0,0.0,0.0)-p
    local y=GetPedBoneCoords(owner,57005,0.0,1.0,0.0)-p
    local z=GetPedBoneCoords(owner,57005,0.0,0.0,1.0)-p
    return p,x,y,z
end
-- Per-weapon mounts are generated by the Blender pipeline. Carbine and AK
-- grip/stock markers differ; applying one offset to both clips into the torso.
local function cleanup()
    if visual and DoesEntityExist(visual) then DeleteEntity(visual) end
    visual=nil
    if owner and DoesEntityExist(owner) then SetPedCurrentWeaponVisible(owner,true,false,true,true) end
    owner=nil
    mount=nil
end
CidadeCombatWeapon.destroy=cleanup
function CidadeCombatWeapon.entity(ped)
    if visual and DoesEntityExist(visual) then return visual end
    return GetCurrentPedWeaponEntityIndex(ped)
end
function CidadeCombatWeapon.update()
    if not owner then return true end
    if not visual or not DoesEntityExist(visual) then return false end
    local p,x,y,z=wristFrame()
    local function transform(v) return x*v[1]+y*v[2]+z*v[3] end
    local right,forward,up=transform(mount.basis[1]),transform(mount.basis[2]),transform(mount.basis[3])
    local at=p+transform(mount.position)
    SetEntityMatrix(visual,forward.x,forward.y,forward.z,right.x,right.y,right.z,up.x,up.y,up.z,at.x,at.y,at.z)
    SetPedCurrentWeaponVisible(owner,false,false,true,true)
    return true
end
function CidadeCombatWeapon.inspect()
    if not owner or not mount or not visual or not DoesEntityExist(owner) or not DoesEntityExist(visual) then return nil end
    local p,x,y,z=wristFrame()
    local function transform(v) return x*v[1]+y*v[2]+z*v[3] end
    local barrel=transform(mount.basis[1]) -- weapon model's longitudinal X axis
    local length=math.sqrt(barrel.x^2+barrel.y^2+barrel.z^2)
    if length<0.001 then return {invalidBasis=true} end
    local _,_,pedUp=GetEntityMatrix(owner)
    local upLength=math.sqrt(pedUp.x^2+pedUp.y^2+pedUp.z^2)
    if upLength<0.001 then return {invalidBasis=true} end
    local vertical=(barrel.x*pedUp.x+barrel.y*pedUp.y+barrel.z*pedUp.z)/(length*upLength)
    local left=GetPedBoneCoords(owner,18905,0.0,0.0,0.0)
    local function xyz(v)return {v.x,v.y,v.z}end
    return {entity=visual,owner=owner,barrelPitch=math.deg(math.asin(math.max(-1,math.min(1,vertical)))),
        worldBarrelPitch=math.deg(math.asin(math.max(-1,math.min(1,barrel.z/length)))),
        barrelDirection=xyz(barrel),rightWrist=xyz(p),leftWrist=xyz(left),basisLength=length}
end
function CidadeCombatWeapon.create(ped,weapon)
    cleanup()
    mount=CidadeCombatMounts[weapon]
    if not mount then return false end
    local p=GetEntityCoords(ped)
    visual=CreateWeaponObject(weapon,1,p.x,p.y,p.z,true,1.0,0,false,false)
    if not visual or visual==0 or not DoesEntityExist(visual) then visual=nil;mount=nil;return false end
    owner=ped
    SetEntityAsMissionEntity(visual,true,true)
    SetEntityCollision(visual,false,false);FreezeEntityPosition(visual,true)
    SetWeaponObjectTintIndex(visual,GetPedWeaponTintIndex(ped,weapon))
    for _,name in ipairs({'COMPONENT_CARBINERIFLE_CLIP_02','COMPONENT_CARBINERIFLE_CLIP_03',
        'COMPONENT_ASSAULTRIFLE_CLIP_02','COMPONENT_ASSAULTRIFLE_CLIP_03',
        'COMPONENT_AT_AR_FLSH','COMPONENT_AT_AR_AFGRIP','COMPONENT_AT_SCOPE_MEDIUM',
        'COMPONENT_AT_SCOPE_MACRO','COMPONENT_AT_AR_SUPP','COMPONENT_AT_AR_SUPP_02',
        'COMPONENT_CARBINERIFLE_VARMOD_LUXE','COMPONENT_ASSAULTRIFLE_VARMOD_LUXE'}) do
        local component=joaat(name)
        if HasPedGotWeaponComponent(ped,weapon,component) then GiveWeaponComponentToWeaponObject(visual,component) end
    end
    CidadeCombatWeapon.update()
    return true
end
AddEventHandler('onResourceStop',function(resource)
    if resource==GetCurrentResourceName() then cleanup() end
end)
